120	export function handleQueryRequest<S extends Schema>(
121	  transformQuery: TransformQueryFunction,
122	  schema: S,
123	  requestOrJsonBody: Request | ReadonlyJSONValue,
124	  logLevelOrOptions?: LogLevel | QueryRequestOptions,
125	): Promise<QueryResponse> {
126	  const options = normalizeQueryRequestOptions(logLevelOrOptions);
127	  const normalized: NormalizedQueryRequestArgs = {
128	    requestOrJsonBody,
129	    userID: 'userID' in options ? (options.userID ?? null) : undefined,
130	    logLevel: options.logLevel ?? 'info',
131	  };
132	
133	  return transform(
134	    (name, argsArray) => transformQuery(name, argsArray[0]),
135	    schema,
136	    normalized.userID,
137	    normalized.requestOrJsonBody,
138	    'query',
139	    normalized.logLevel,
140	  );
141	}
