143	function normalizeQueryRequestOptions(
144	  logLevelOrOptions: LogLevel | QueryRequestOptions | undefined,
145	): QueryRequestOptions {
146	  return typeof logLevelOrOptions === 'string'
147	    ? {logLevel: logLevelOrOptions}
148	    : (logLevelOrOptions ?? {});
149	}
