  return {
    async transaction(cb) {
      let lmid = 0;
      return cb({} as unknown, {
        async updateClientMutationID() {
          lmid += 1;
          return {lastMutationID: lmid};
        },
        async writeMutationResult() {},
        async deleteMutationResults() {},
      });
    },
  };
}

