      {
        type: 'custom' as const,
        id: 1,
        clientID: 'cid',
        name: 'foo',
        args: [{}],
        timestamp: 1,
      },
    ],
    pushVersion: 1,
    schemaVersion: 1,
    timestamp: 1,
    requestID: 'req',
  };
}

